/* roots.c -- the matrix roots of unity I_s^k from the MFFT post.
 *
 * The post represents the 2^(s+1)-th roots of unity as 2^s x 2^s signed
 * permutation matrices I_s, generated by I_{s+1} = [[0, I_s], [1, 0]], and
 * gives a recursion for H_{s,k}, a compact encoding of I_s^k: H[j] is the
 * (1-based) column of the single non-zero entry in row j, negated when that
 * entry is -1.
 *
 *   H_{s,k}[j] = -H_{s,k-1}[2^s]              if j = 1
 *                 H_{s,k-1}[2^s - 1]           if j = 2
 *                 H_{s,k-1}[2^(s-1) + j - 2]   if 2 < j <= 2^(s-1)
 *                 H_{s,k-1}[j - 2^(s-1)]       if j > 2^(s-1)
 *
 * What the transform actually needs from all this is one fact:
 *
 *     I_s has multiplicative order 2K and I_s^K = -1,  K = 2^s.
 *
 * That makes Z[I_s] isomorphic to R = Z[y]/(y^K + 1), and if a ring element
 * is written in the *power basis* sum_c v_c I_s^c, then multiplying by I_s^e
 * is a negacyclic shift of the coefficient vector -- pure data movement plus
 * sign flips, no multiplications.  mfft.c stores ring elements that way, so
 * it never materialises an I_s^k matrix.  These tables exist to verify the
 * post's recursion and to check the order/negation property the transform
 * depends on.
 */
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include "mfftbench.h"

/* returns [(2K) * K] with 0-based row index; entries are signed 1-based cols */
int *roots_build_H(int s)
{
    int K = 1 << s;
    int N = 1 << (s + 1);          /* order of I_s */
    int half = K / 2;
    int *H = malloc((size_t)N * K * sizeof(int));
    if (!H) return NULL;

    for (int j = 1; j <= K; j++) H[j - 1] = j;      /* H_{s,0} = identity */

    for (int k = 1; k < N; k++) {
        const int *prev = H + (size_t)(k - 1) * K;
        int *cur = H + (size_t)k * K;
        for (int j = 1; j <= K; j++) {
            int v;
            if (j == 1)            v = -prev[K - 1];
            else if (j == 2)       v =  prev[K - 2];
            else if (j <= half)    v =  prev[half + j - 2 - 1];
            else                   v =  prev[j - half - 1];
            cur[j - 1] = v;
        }
    }
    return H;
}

/* dense +-1 matrix for H_{s,k}: M[row*K + col] */
static void h_to_matrix(const int *Hk, int K, int *M)
{
    for (int i = 0; i < K * K; i++) M[i] = 0;
    for (int j = 0; j < K; j++) {
        int v = Hk[j];
        int col = (v > 0 ? v : -v) - 1;
        M[j * K + col] = (v > 0) ? 1 : -1;
    }
}

static void mat_mul(const int *A, const int *B, int *C, int K)
{
    for (int i = 0; i < K; i++)
        for (int j = 0; j < K; j++) {
            int acc = 0;
            for (int k = 0; k < K; k++) acc += A[i * K + k] * B[k * K + j];
            C[i * K + j] = acc;
        }
}

/* rank of the K x K^2 matrix whose rows are flattened I_s^0..I_s^(K-1) */
static int power_basis_rank(const int *H, int K)
{
    int cols = K * K;
    double *M = calloc((size_t)K * cols, sizeof(double));
    int *tmp = malloc((size_t)K * K * sizeof(int));
    if (!M || !tmp) { free(M); free(tmp); return -1; }

    for (int p = 0; p < K; p++) {
        h_to_matrix(H + (size_t)p * K, K, tmp);
        for (int i = 0; i < cols; i++) M[(size_t)p * cols + i] = tmp[i];
    }
    int rank = 0;
    for (int c = 0; c < cols && rank < K; c++) {
        int piv = -1; double best = 1e-9;
        for (int r = rank; r < K; r++) {
            double a = fabs(M[(size_t)r * cols + c]);
            if (a > best) { best = a; piv = r; }
        }
        if (piv < 0) continue;
        for (int i = 0; i < cols; i++) {
            double t = M[(size_t)rank * cols + i];
            M[(size_t)rank * cols + i] = M[(size_t)piv * cols + i];
            M[(size_t)piv * cols + i] = t;
        }
        double p0 = M[(size_t)rank * cols + c];
        for (int r = 0; r < K; r++) {
            if (r == rank) continue;
            double f = M[(size_t)r * cols + c] / p0;
            if (f == 0.0) continue;
            for (int i = c; i < cols; i++)
                M[(size_t)r * cols + i] -= f * M[(size_t)rank * cols + i];
        }
        rank++;
    }
    free(M); free(tmp);
    return rank;
}

/* the three sample rows printed in the post, as a regression check */
static const int post_H11[] = { -2, 1 };
static const int post_H21[] = { -4, 3, 1, 2 };
static const int post_H23[] = { -3, -4, -2, 1 };
static const int post_H31[] = { -8, 7, 5, 6, 1, 2, 3, 4 };
static const int post_H35[] = { -7, -8, -6, 5, -2, 1, -4, 3 };

static int cmp_row(const int *got, const int *want, int K, const char *lbl,
                   int verbose)
{
    for (int i = 0; i < K; i++)
        if (got[i] != want[i]) {
            printf("  FAIL %s: got[%d]=%d want %d\n", lbl, i, got[i], want[i]);
            return 0;
        }
    if (verbose) {
        printf("  ok   %s = [", lbl);
        for (int i = 0; i < K; i++) printf("%s%d", i ? "," : "", got[i]);
        printf("]\n");
    }
    return 1;
}

int roots_selftest(int max_s, int verbose)
{
    int ok = 1;
    printf("roots-of-unity self test (H_{s,k} recursion from the post)\n");

    for (int s = 1; s <= max_s; s++) {
        int K = 1 << s, N = 1 << (s + 1);
        int *H = roots_build_H(s);
        if (!H) return 0;

        int *M   = malloc((size_t)K * K * sizeof(int));
        int *P   = malloc((size_t)K * K * sizeof(int));
        int *Q   = malloc((size_t)K * K * sizeof(int));
        int *cur = malloc((size_t)K * K * sizeof(int));
        h_to_matrix(H + (size_t)1 * K, K, M);          /* generator I_s */
        h_to_matrix(H, K, cur);                        /* identity      */

        int good = 1;
        for (int k = 1; k < N; k++) {
            mat_mul(cur, M, P, K);                     /* P = I_s^k     */
            h_to_matrix(H + (size_t)k * K, K, Q);      /* table version */
            for (int i = 0; i < K * K; i++)
                if (P[i] != Q[i]) { good = 0; break; }
            if (!good) { printf("  FAIL s=%d: H_{s,%d} != I_s^%d\n", s, k, k);
                         break; }
            for (int i = 0; i < K * K; i++) cur[i] = P[i];

            if (k == K) {   /* I_s^K must be -1 : this is what MFFT needs */
                for (int i = 0; i < K; i++)
                    for (int j = 0; j < K; j++) {
                        int want = (i == j) ? -1 : 0;
                        if (P[i * K + j] != want) {
                            printf("  FAIL s=%d: I_s^%d != -1\n", s, K);
                            good = 0;
                        }
                    }
            }
        }
        /* one more step must land back on the identity */
        mat_mul(cur, M, P, K);
        for (int i = 0; i < K; i++)
            for (int j = 0; j < K; j++)
                if (P[i * K + j] != (i == j)) {
                    printf("  FAIL s=%d: I_s^%d != 1\n", s, N); good = 0;
                }

        int rank = power_basis_rank(H, K);
        if (rank != K) {
            printf("  FAIL s=%d: powers I_s^0..I_s^%d span rank %d (want %d)\n",
                   s, K - 1, rank, K);
            good = 0;
        }

        if (good && verbose)
            printf("  ok   s=%d K=%d: order %d, I_s^%d = -1, power basis rank %d\n",
                   s, K, N, K, rank);
        ok &= good;
        free(H); free(M); free(P); free(Q); free(cur);
    }

    /* regression against the arrays printed in the post */
    int *H1 = roots_build_H(1), *H2 = roots_build_H(2), *H3 = roots_build_H(3);
    ok &= cmp_row(H1 + 1 * 2, post_H11, 2, "H_{1,1}", verbose);
    ok &= cmp_row(H2 + 1 * 4, post_H21, 4, "H_{2,1}", verbose);
    ok &= cmp_row(H2 + 3 * 4, post_H23, 4, "H_{2,3}", verbose);
    ok &= cmp_row(H3 + 1 * 8, post_H31, 8, "H_{3,1}", verbose);
    ok &= cmp_row(H3 + 5 * 8, post_H35, 8, "H_{3,5}", verbose);
    free(H1); free(H2); free(H3);

    printf("roots self test: %s\n", ok ? "PASS" : "FAIL");
    return ok;
}
